void run() {
	std::cout << std::endl << "==> using CPU" << std::endl;
	DeviceOption device_option;
	std::shared_ptr<CPUContext> ctx_cpu;
	device_option.set_device_type(CPU);
	ctx_cpu.reset(new CPUContext(device_option));
	std::cout << std::endl << "==> using CPU" << std::endl;


